10	package org.elasticsearch.geometry.simplify;
11	
12	import java.util.Locale;
13	
14	import static java.lang.Math.acos;
15	import static java.lang.Math.min;
16	import static org.elasticsearch.geometry.simplify.SimplificationErrorCalculator.Point3D.sin;
17	import static org.elasticsearch.geometry.simplify.SloppyMath.cos;
18	
19	public interface SimplificationErrorCalculator {
20	    double calculateError(PointLike left, PointLike middle, PointLike right);
21	
22	    interface PointLike {
23	        double x();
24	
25	        double y();
26	    }
27	
28	    SimplificationErrorCalculator CARTESIAN_TRIANGLE_AREA = new CartesianTriangleAreaCalculator();
29	    SimplificationErrorCalculator TRIANGLE_AREA = new TriangleAreaCalculator();
30	    SimplificationErrorCalculator TRIANGLE_HEIGHT = new TriangleHeightCalculator();
31	    SimplificationErrorCalculator HEIGHT_AND_BACKPATH_DISTANCE = new CartesianHeightAndBackpathDistanceCalculator();
32	    SimplificationErrorCalculator SPHERICAL_HEIGHT_AND_BACKPATH_DISTANCE = new SphericalHeightAndBackpathDistanceCalculator();
33	
34	    static SimplificationErrorCalculator byName(String calculatorName) {
35	        return switch (calculatorName.toLowerCase(Locale.ROOT)) {
36	            case "cartesiantrianglearea" -> CARTESIAN_TRIANGLE_AREA;
37	            case "trianglearea" -> TRIANGLE_AREA;
38	            case "triangleheight" -> TRIANGLE_HEIGHT;
39	            case "heightandbackpathdistance" -> HEIGHT_AND_BACKPATH_DISTANCE;
40	            case "sphericalheightandbackpathdistance" -> SPHERICAL_HEIGHT_AND_BACKPATH_DISTANCE;
41	            default -> throw new IllegalArgumentException("Unknown simplification error calculator: " + calculatorName);
42	        };
43	    }
44	
45	    /**
46	     * Calculate the triangle area using cartesian coordinates as described at
47	     * <a href="https://en.wikipedia.org/wiki/Area_of_a_triangle">Area of a triangle</a>
48	     */
49	    class CartesianTriangleAreaCalculator implements SimplificationErrorCalculator {
50	
51	        @Override
52	        public double calculateError(PointLike left, PointLike middle, PointLike right) {
53	            double xb = middle.x() - left.x();
54	            double yb = middle.y() - left.y();
55	            double xc = right.x() - left.x();
56	            double yc = right.y() - left.y();
57	            return 0.5 * Math.abs(xb * yc - xc * yb);
58	        }
59	    }
60	
61	    /**
62	     * Calculate the triangle area using geographic coordinates and Herons formula (side lengths) as described at
63	     * <a href="https://en.wikipedia.org/wiki/Area_of_a_triangle">Area of a triangle</a>
64	     */
65	    class TriangleAreaCalculator implements SimplificationErrorCalculator {
66	
67	        @Override
68	        public double calculateError(PointLike left, PointLike middle, PointLike right) {
69	            // Calculate side lengths using approximate haversine
70	            double a = distance(left, right);
71	            double b = distance(right, middle);
72	            double c = distance(middle, left);
73	            // semi-perimeter
74	            double s = 0.5 * (a + b + c);  // Semi-perimeter
75	            double da = s - a;
76	            double db = s - b;
77	            double dc = s - c;
78	            if (da >= 0 && db >= 0 && dc >= 0) {
79	                // Herons formula
80	                return Math.sqrt(s * da * db * dc);
81	            } else {
82	                // rounding errors can cause flat triangles to have negative values, leading to NaN areas
83	                return 0.0;
84	            }
85	        }
86	
87	        private static double distance(PointLike a, PointLike b) {
88	            return SloppyMath.haversinMeters(a.y(), a.x(), b.y(), b.x());
89	        }
90	    }
91	
92	    /**
93	     * Calculate the triangle area using geographic coordinates and Herons formula (side lengths) as described at
94	     * <a href="https://en.wikipedia.org/wiki/Area_of_a_triangle">Area of a triangle</a>, but scale the area down
95	     * by the inverse of the length of the base (left-right), which estimates the height of the triangle.
96	     */
97	    class TriangleHeightCalculator implements SimplificationErrorCalculator {
98	
99	        @Override
100	        public double calculateError(PointLike left, PointLike middle, PointLike right) {
101	            // Calculate side lengths using approximate haversine
102	            double a = distance(left, right);
103	            double b = distance(right, middle);
104	            double c = distance(middle, left);
105	            // semi-perimeter
106	            double s = 0.5 * (a + b + c);  // Semi-perimeter
107	            double da = s - a;
108	            double db = s - b;
109	            double dc = s - c;
110	            if (da >= 0 && db >= 0 && dc >= 0) {
111	                // Herons formula, scaled by 2/a to estimate height
112	                return 2.0 * Math.sqrt(s * da * db * dc) / a;
113	            } else {
114	                // rounding errors can cause flat triangles to have negative values, leading to NaN areas
115	                return 0.0;
116	            }
117	        }
118	
119	        private static double distance(PointLike a, PointLike b) {
120	            return SloppyMath.haversinMeters(a.y(), a.x(), b.y(), b.x());
121	        }
122	    }
123	
124	    /**
125	     * Estimate the error as the height of the point above the base, but including support for back-paths
126	     * in the sense that of the point to be removed is father from either end than the height, we take that distance instead.
127	     * <p>
128	     * Rotate all three points such that left-right are a horizontal line on the x-axis. Then the numbers of interest are:
129	     * <ol>
130	     *     <li>height: y-value of middle point</li>
131	     *     <li>deltaL: -min(0, middleX - leftX)</li>
132	     *     <li>deltaR: max(0, middleX - rightX)</li>
133	     * </ol>
134	     * And the final error is: error = max(height, max(deltaL, deltaR))
135	     * <p>
136	     * This is not a full Frechet error calculation as it does not maintain state of all removed points,
137	     * only calculating the error incurred by removal of the current point, as if the current simplified line is
138	     * a good enough approximation of the original line. This restriction is currently true of all the
139	     * calculations implemented so far.
140	     */
141	    class CartesianHeightAndBackpathDistanceCalculator implements SimplificationErrorCalculator {
142	
143	        @Override
144	        public double calculateError(PointLike left, PointLike middle, PointLike right) {
145	            // Offset coordinates so left is at the origin
146	            double rightX = right.x() - left.x();
147	            double rightY = right.y() - left.y();
148	            if (Math.abs(rightX) > 1e-10 || Math.abs(rightY) > 1e-10) {
149	                // Rotate coordinates so that left->right is horizontal
150	                double len = Math.sqrt(rightX * rightX + rightY * rightY);
151	                double cos = rightX / len;
152	                double sin = rightY / len;
153	                double middleX = middle.x() - left.x();
154	                double middleY = middle.y() - left.y();
155	                double middleXrotated = middleX * cos + middleY * sin;
156	                double middleYrotated = middleY * cos - middleX * sin;
157	                double rightXrotated = rightX * cos + rightY * sin;
158	                double rightYrotated = rightY * cos - rightX * sin;
159	                assert Math.abs(rightYrotated) < 1e-10;
160	                assert Math.abs(rightXrotated - len) < len / 1e10;
161	                double height = Math.abs(middleYrotated);
162	                double deltaL = -min(0, middleXrotated);
163	                double deltaR = Math.max(0, middleXrotated - rightXrotated);
164	                double backDistance = Math.max(deltaR, deltaL);
165	                return Math.max(height, backDistance);
166	            } else {
167	                // If left and right points are co-located, we assume no consequence to removing the middle point
168	                return 0.0;
169	            }
170	        }
171	    }
172	
173	    /**
174	     * Estimate the error as the height of the point above the base, but including support for back-paths
175	     * in the sense that of the point to be removed is father from either end than the height, we take that distance instead.
176	     * <p>
177	     * Rotate all three points such that left-right are a horizontal line on the x-axis. Then the numbers of interest are:
178	     * <ol>
179	     *     <li>height: y-value of middle point</li>
180	     *     <li>deltaL: -min(0, middleX - leftX)</li>
181	     *     <li>deltaR: max(0, middleX - rightX)</li>
182	     * </ol>
183	     * And the final error is: error = max(height, max(deltaL, deltaR))
184	     * <p>
185	     * This is not a full Frechet error calculation as it does not maintain state of all removed points,
186	     * only calculating the error incurred by removal of the current point, as if the current simplified line is
187	     * a good enough approximation of the original line. This restriction is currently true of all the
188	     * calculations implemented so far.
189	     */
190	    class SphericalHeightAndBackpathDistanceCalculator implements SimplificationErrorCalculator {
191	        @Override
192	        public double calculateError(PointLike leftLL, PointLike middleLL, PointLike rightLL) {
193	            // Convert to 3D
194	            Point3D left = Point3D.from(leftLL);
195	            Point3D middle = Point3D.from(middleLL);
196	            Point3D right = Point3D.from(rightLL);
197	
198	            // Rotate to horizontal
199	            Point3D rotationAxis = right.cross(left);
200	            Point3D xAxis = new Point3D(1, 0, 0);
201	            double rotationAngle = xAxis.angleTo(left);
202	            left = left.rotate(rotationAxis, rotationAngle);
203	            middle = middle.rotate(rotationAxis, rotationAngle);
204	            right = right.rotate(rotationAxis, rotationAngle);
205	            double len = left.angleTo(right);
206	            if (len > 1e-10) {
207	                double height = Math.abs(middle.z);
208	                double deltaL = -min(0, middle.y);
209	                double deltaR = Math.max(0, middle.y - right.y);
210	                double backDistance = Math.max(deltaR, deltaL);
211	                return Math.max(height, backDistance);
212	            } else {
213	                // If left and right points are co-located, we assume no consequence to removing the middle point
214	                return 0.0;
215	            }
216	        }
217	    }
218	
219	    /** This record captures a point defined using a 3D vector (x, y, z) */
220	    record Point3D(double x, double y, double z) {
221	        /** Convert a geographic point from latitude/longitude to x,y,z of unit length */
222	        public static Point3D from(double latDegrees, double lonDegrees) {
223	            double lat = Math.toRadians(latDegrees);
224	            double lon = Math.toRadians(lonDegrees);
225	            double x = cos(lat) * cos(lon);
226	            double y = cos(lat) * sin(lon);
227	            double z = sin(lat);
228	            return new Point3D(x, y, z);
229	        }
230	
231	        /** Convert a geographic point from latitude/longitude to x,y,z */
232	        public static Point3D from(PointLike point) {
233	            return from(point.y(), point.x());
234	        }
235	
236	        /** Vector cross-product of this vector against the provided vector */
237	        public Point3D cross(Point3D o) {
238	            return new Point3D(y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x);
239	        }
240	
241	        static double sin(double radians) {
242	            return cos(radians - Math.PI / 2);
243	        }
244	
245	        /** Calculate the length of this vector, should be 1 for unit vectors */
246	        public double length() {
247	            return Math.sqrt(x * x + y * y + z * z);
248	        }
249	
250	        /** Invert this vector, providing a parallel vector pointing in the opposite direction */
251	        public Point3D inverse() {
252	            return new Point3D(-x, -y, -z);
253	        }
254	
255	        /** Calculate the angle in radians between this vector and the specified vector */
256	        public double angleTo(Point3D other) {
257	            double a = this.dot(other) / (this.length() * other.length());
258	            return acos(min(1.0, a));
259	        }
260	
261	        /** Calculate the dot-product of this vector with the specified vector */
262	        public double dot(Point3D o) {
263	            return x * o.x + y * o.y + z * o.z;
264	        }
265	
266	        /** Rotate this vector about the specified axis, by the specified angle in radian */
267	        public Point3D rotate(Point3D rotationAxis, double rotationAngle) {
268	            RotationMatrix rotation = new RotationMatrix(rotationAxis, rotationAngle);
269	            return rotation.multiply(this);
270	        }
271	    }
272	
273	    /**
274	     * This 3D rotation matrix allows for rotating 3D vectors (eg. Point3D above) about a specified axis (also Point3D)
275	     * and by a specified angle in radian.
276	     */
277	    record RotationMatrix(double[][] matrix) {
278	        public RotationMatrix {
279	            assert matrix.length == 3;
280	            for (double[] doubles : matrix) {
281	                assert doubles.length == 3;
282	            }
283	        }
284	
285	        public RotationMatrix(Point3D axis, double angleInRadian) {
286	            this(matrixFrom(axis, angleInRadian));
287	        }
288	
289	        /** Perform the rotation by multiplying this matrix by the incoming vector */
290	        public Point3D multiply(Point3D incoming) {
291	            double x = dot(incoming, matrix[0]);
292	            double y = dot(incoming, matrix[1]);
293	            double z = dot(incoming, matrix[2]);
294	            return new Point3D(x, y, z);
295	        }
296	
297	        private static double dot(Point3D incoming, double[] row) {
298	            return incoming.x * row[0] + incoming.y * row[1] + incoming.z * row[2];
299	        }
300	
301	        /**
302	         * Create the actual rotation matrix cell values according to the formulas at
303	         * <a href="https://en.wikipedia.org/wiki/Rotation_matrix#Rotation_matrix_from_axis_and_angle">Rotation matrix (wikipedia)</a>
304	         */
305	        private static double[][] matrixFrom(Point3D axis, double angle) {
306	            double[][] matrix = new double[3][];
307	            double x = axis.x;
308	            double y = axis.y;
309	            double z = axis.z;
310	            matrix[0] = new double[] { diag(angle, x), cell(angle, x, y, -z), cell(angle, x, z, y) };
311	            matrix[1] = new double[] { cell(angle, y, x, z), diag(angle, y), cell(angle, y, z, -x) };
312	            matrix[2] = new double[] { cell(angle, z, x, -y), cell(angle, z, y, x), diag(angle, z) };
313	            return matrix;
314	        }
315	
316	        /** The values along the diagonal */
317	        private static double diag(double angle, double coord) {
318	            double cosTheta = cos(angle);
319	            return cosTheta + coord * coord * (1 - cosTheta);
320	        }
321	
322	        /** The values along the diagonal */
323	        private static double cell(double angle, double a, double b, double c) {
324	            return a * b * (1 - cos(angle)) + c * sin(angle);
325	        }
326	    }
327	}
